/**
 * Action 4 Prompt Module for tx-4-imp-1 Agent
 * 
 * Responsibility: Generate prompt for automated course extraction and priority judgment
 * from collected daily reports and identification of bottlenecks.
 * 
 * Part of workflow: Confirm email content reading → Aggregate overall progress →
 * Extract issues/bottlenecks → Judge and classify issue priorities
 */

export const ACTION_04_PROMPT_VERSION = "1.0.0";

export interface Action04PromptContext {
  collectedReports: DailyReport[];
  reportingPeriod: {
    startDate: string;
    endDate: string;
  };
  teamMembers: TeamMember[];
  previousIssues?: ExtractedIssue[];
  priorityClassificationRules?: PriorityRule[];
}

export interface DailyReport {
  reportId: string;
  employeeId: string;
  employeeName: string;
  submittedAt: string;
  yesterdayAccomplishments: string;
  todayPlans: string;
  currentIssues: string;
  blockers?: string;
  progressPercentage?: number;
}

export interface TeamMember {
  employeeId: string;
  name: string;
  department: string;
  role: string;
}

export interface ExtractedIssue {
  issueId: string;
  title: string;
  description: string;
  affectedEmployees: string[];
  category: "technical" | "resource" | "dependency" | "process" | "other";
  severity: "critical" | "high" | "medium" | "low";
  detectedAt: string;
}

export interface PriorityRule {
  ruleId: string;
  condition: string;
  priority: number;
  category: string;
}

export interface Action04PromptOutput {
  systemPrompt: string;
  userPrompt: string;
  context: Action04PromptContext;
}

/**
 * Builds the prompt for Action 4: Extract issues and judge priorities
 * 
 * This action processes collected daily reports to:
 * 1. Identify common issues and bottlenecks across team
 * 2. Categorize issues by type and impact
 * 3. Assign priority levels based on severity and scope
 * 4. Prepare structured issue list for manager review
 * 
 * @param context - The context containing collected reports and team information
 * @returns Structured prompt with system and user instructions
 */
export function buildAction04Prompt(
  context: Action04PromptContext
): Action04PromptOutput {
  const systemPrompt = buildSystemPrompt();
  const userPrompt = buildUserPrompt(context);

  return {
    systemPrompt,
    userPrompt,
    context,
  };
}

function buildSystemPrompt(): string {
  return `You are an expert AI assistant specialized in analyzing daily reports and extracting critical issues and bottlenecks from team progress data.

Your responsibilities:
1. Analyze collected daily reports to identify common themes, blockers, and issues
2. Extract issues with clear categorization (technical, resource, dependency, process, other)
3. Assess severity based on impact scope and urgency indicators
4. Assign priority levels considering:
   - Number of affected team members
   - Impact on project timeline
   - Dependencies on other teams or systems
   - Frequency of recurrence
   - Escalation indicators in report content
5. Provide structured, actionable insights for management decision-making

Guidelines:
- Focus on issues that impact team productivity or project delivery
- Identify patterns across multiple reports (not just isolated incidents)
- Consider both explicit blockers and implicit issues (e.g., low progress percentage)
- Maintain objectivity and avoid subjective interpretation
- Flag issues that deviate from normal patterns
- Provide clear reasoning for priority assignments
- Group related issues to avoid duplication

Output format must be JSON-compatible and include:
- Issue ID and title
- Detailed description with evidence from reports
- Affected employees and departments
- Category and severity assessment
- Recommended priority level (1-5, where 1 is highest)
- Suggested action or escalation path`;
}

function buildUserPrompt(context: Action04PromptContext): string {
  const reportsSummary = formatReportsSummary(context.collectedReports);
  const teamContext = formatTeamContext(context.teamMembers);
  const rulesContext = formatPriorityRules(context.priorityClassificationRules);
  const previousContext = formatPreviousIssues(context.previousIssues);

  return `Analyze the following daily reports collected for the period ${context.reportingPeriod.startDate} to ${context.reportingPeriod.endDate} and extract issues with priority classification.

TEAM CONTEXT:
${teamContext}

COLLECTED DAILY REPORTS:
${reportsSummary}

PRIORITY CLASSIFICATION RULES:
${rulesContext}

PREVIOUS ISSUES (for pattern tracking):
${previousContext}

TASK:
1. Extract all distinct issues and bottlenecks from the reports
2. Categorize each issue by type
3. Assess severity based on impact and scope
4. Assign priority levels (1=Critical, 2=High, 3=Medium, 4=Low, 5=Informational)
5. Identify patterns or recurring issues
6. Flag any issues that require immediate escalation
7. Provide recommendations for each issue

Return a structured JSON response containing:
{
  "extractedIssues": [
    {
      "issueId": "string",
      "title": "string",
      "description": "string",
      "category": "technical|resource|dependency|process|other",
      "severity": "critical|high|medium|low",
      "priority": number,
      "affectedEmployees": ["string"],
      "evidence": ["string"],
      "recurrencePattern": "string or null",
      "recommendedAction": "string",
      "requiresEscalation": boolean
    }
  ],
  "summary": {
    "totalIssuesExtracted": number,
    "criticalCount": number,
    "highCount": number,
    "mediumCount": number,
    "lowCount": number,
    "recurringIssues": ["string"],
    "newIssues": ["string"]
  },
  "insights": {
    "overallTeamHealth": "string",
    "mainBottlenecks": ["string"],
    "recommendedFocusAreas": ["string"],
    "escalationRequired": boolean,
    "escalationReason": "string or null"
  }
}`;
}

function formatReportsSummary(reports: DailyReport[]): string {
  if (!reports || reports.length === 0) {
    return "No reports collected.";
  }

  return reports
    .map(
      (report) => `
[${report.employeeName} - ${report.employeeId}]
Submitted: ${report.submittedAt}
Yesterday's Accomplishments: ${report.yesterdayAccomplishments}
Today's Plans: ${report.todayPlans}
Current Issues: ${report.currentIssues}
${report.blockers ? `Blockers: ${report.blockers}` : ""}
${report.progressPercentage !== undefined ? `Progress: ${report.progressPercentage}%` : ""}
`
    )
    .join("\n---\n");
}

function formatTeamContext(members: TeamMember[]): string {
  if (!members || members.length === 0) {
    return "No team member information available.";
  }

  return members
    .map(
      (member) =>
        `- ${member.name} (${member.employeeId}): ${member.role} in ${member.department}`
    )
    .join("\n");
}

function formatPriorityRules(rules?: PriorityRule[]): string {
  if (!rules || rules.length === 0) {
    return `Default priority rules:
1. Critical: Blocks multiple team members or project delivery
2. High: Impacts team productivity or timeline
3. Medium: Affects individual contributor or non-critical path
4. Low: Minor inconvenience or informational`;
  }

  return rules
    .map(
      (rule) =>
        `Priority ${rule.priority} (${rule.category}): ${rule.condition}`
    )
    .join("\n");
}

function formatPreviousIssues(issues?: ExtractedIssue[]): string {
  if (!issues || issues.length === 0) {
    return "No previous issues on record.";
  }

  return issues
    .map(
      (issue) =>
        `- [${issue.category}] ${issue.title} (Severity: ${issue.severity})`
    )
    .join("\n");
}
